static void aw_AQuickVoiceClip_process_fast(void *aw_state, int16_t *aw_out,
    const int16_t *aw_in, int32_t sampleFrames, uint32_t aw_channels) {
    aw_AQuickVoiceClip_fast_t *aw_s = (aw_AQuickVoiceClip_fast_t *)aw_state;
    const double aw_sample_rate = aw_s->aw_sample_rate;
    (void)aw_sample_rate;
    float LataLast6Sample = aw_s->LataLast6Sample;
    float LataLast5Sample = aw_s->LataLast5Sample;
    float LataLast4Sample = aw_s->LataLast4Sample;
    float LataLast3Sample = aw_s->LataLast3Sample;
    float LataLast2Sample = aw_s->LataLast2Sample;
    float LataLast1Sample = aw_s->LataLast1Sample;
    float LataHalfwaySample = aw_s->LataHalfwaySample;
    float LataHalfDrySample = aw_s->LataHalfDrySample;
    float LataHalfDiffSample = aw_s->LataHalfDiffSample;
    float LataLastDiffSample = aw_s->LataLastDiffSample;
    float LataDrySample = aw_s->LataDrySample;
    float LataDiffSample = aw_s->LataDiffSample;
    float RataLast6Sample = aw_s->RataLast6Sample;
    float RataLast5Sample = aw_s->RataLast5Sample;
    float RataLast4Sample = aw_s->RataLast4Sample;
    float RataLast3Sample = aw_s->RataLast3Sample;
    float RataLast2Sample = aw_s->RataLast2Sample;
    float RataLast1Sample = aw_s->RataLast1Sample;
    float RataHalfwaySample = aw_s->RataHalfwaySample;
    float RataHalfDrySample = aw_s->RataHalfDrySample;
    float RataHalfDiffSample = aw_s->RataHalfDiffSample;
    float RataLastDiffSample = aw_s->RataLastDiffSample;
    float RataDrySample = aw_s->RataDrySample;
    float RataDiffSample = aw_s->RataDiffSample;
    float ataK1 = aw_s->ataK1;
    float ataK2 = aw_s->ataK2;
    float ataK3 = aw_s->ataK3;
    float ataK4 = aw_s->ataK4;
    float ataK5 = aw_s->ataK5;
    float ataK6 = aw_s->ataK6;
    float ataK7 = aw_s->ataK7;
    float ataK8 = aw_s->ataK8;
    float LlastSample = aw_s->LlastSample;
    float LlastOutSample = aw_s->LlastOutSample;
    float LlastOut2Sample = aw_s->LlastOut2Sample;
    float LlastOut3Sample = aw_s->LlastOut3Sample;
    float LlpDepth = aw_s->LlpDepth;
    float Loverall = aw_s->Loverall;
    float LiirSampleA = aw_s->LiirSampleA;
    float LiirSampleB = aw_s->LiirSampleB;
    float LiirSampleC = aw_s->LiirSampleC;
    float LiirSampleD = aw_s->LiirSampleD;
    float RlastSample = aw_s->RlastSample;
    float RlastOutSample = aw_s->RlastOutSample;
    float RlastOut2Sample = aw_s->RlastOut2Sample;
    float RlastOut3Sample = aw_s->RlastOut3Sample;
    float RlpDepth = aw_s->RlpDepth;
    float Roverall = aw_s->Roverall;
    float RiirSampleA = aw_s->RiirSampleA;
    float RiirSampleB = aw_s->RiirSampleB;
    float RiirSampleC = aw_s->RiirSampleC;
    float RiirSampleD = aw_s->RiirSampleD;
    bool flip = aw_s->flip;
    uint32_t fpdL = aw_s->fpdL;
    uint32_t fpdR = aw_s->fpdR;
    float A = aw_s->A;
    {

	double overallscale = 1.0;
	overallscale /= 44100.0;
	overallscale *= aw_sample_rate;
	
	double softness = 0.484416;
	double hardness = 1.0 - softness;
	double iirAmount = ((pow(A,3)*2070)+30)/8000.0;
	iirAmount /= overallscale;
	double altAmount = (1.0 - iirAmount);
	double cancelnew = 0.0682276;
	double cancelold = 1.0 - cancelnew;
	double lpSpeed = 0.0009;
	double cliplevel = 0.98;
	double refclip = 0.5; //preset to cut out gain quite a lot. 91%? no touchy unless clip
	
	float LmaxRecent;
	bool LclipOnset;
	float LpassThrough;
	float LoutputSample;
	float LdrySample;
	
	float RmaxRecent;
	bool RclipOnset;
	float RpassThrough;
	float RoutputSample;
	float RdrySample;
	

	float inputSampleL;
	float inputSampleR;
	    
    const float aw_f_softness = (float)softness;
	const float aw_f_hardness = (float)hardness;
	const float aw_f_iirAmount = (float)iirAmount;
	const float aw_f_altAmount = (float)altAmount;
	const float aw_f_cancelnew = (float)cancelnew;
	const float aw_f_cancelold = (float)cancelold;
	const float aw_f_lpSpeed = (float)lpSpeed;
	const float aw_f_cliplevel = (float)cliplevel;
	const float aw_f_refclip = (float)refclip;
	const float aw_inv0 = 1.0f / ( 2.0f);
	const float aw_inv1 = 1.0f / ( 3.6f);
	while (--sampleFrames >= 0)
    {
		const float aw_inL = AW_IN_L(aw_in);
		const float aw_inR = AW_IN_R(aw_in, aw_channels);
		float aw_outL = 0.0f, aw_outR = 0.0f;/* aw:loop */
		inputSampleL = aw_inL;
		inputSampleR = aw_inR;
		if (fabsf(inputSampleL)<1.18e-23f) inputSampleL = fpdL * 1.18e-17f;
		if (fabsf(inputSampleR)<1.18e-23f) inputSampleR = fpdR * 1.18e-17f;
		LpassThrough = LataDrySample = inputSampleL;
		RpassThrough = RataDrySample = inputSampleR;
		
		LataHalfDrySample = LataHalfwaySample = (inputSampleL + LataLast1Sample + (LataLast2Sample*ataK1) + (LataLast3Sample*ataK2) + (LataLast4Sample*ataK6) + (LataLast5Sample*ataK7) + (LataLast6Sample*ataK8)) * aw_inv0;
		LataLast6Sample = LataLast5Sample; LataLast5Sample = LataLast4Sample; LataLast4Sample = LataLast3Sample; LataLast3Sample = LataLast2Sample; LataLast2Sample = LataLast1Sample; LataLast1Sample = inputSampleL;
		//setting up oversampled special antialiasing
		RataHalfDrySample = RataHalfwaySample = (inputSampleR + RataLast1Sample + (RataLast2Sample*ataK1) + (RataLast3Sample*ataK2) + (RataLast4Sample*ataK6) + (RataLast5Sample*ataK7) + (RataLast6Sample*ataK8)) * aw_inv0;
		RataLast6Sample = RataLast5Sample; RataLast5Sample = RataLast4Sample; RataLast4Sample = RataLast3Sample; RataLast3Sample = RataLast2Sample; RataLast2Sample = RataLast1Sample; RataLast1Sample = inputSampleR;
		//setting up oversampled special antialiasing
		LclipOnset = false;
		RclipOnset = false;
		
		
		LmaxRecent = fabsf( LataLast6Sample );
		if (fabsf( LataLast5Sample ) > LmaxRecent ) LmaxRecent = fabsf( LataLast5Sample );
		if (fabsf( LataLast4Sample ) > LmaxRecent ) LmaxRecent = fabsf( LataLast4Sample );
		if (fabsf( LataLast3Sample ) > LmaxRecent ) LmaxRecent = fabsf( LataLast3Sample );
		if (fabsf( LataLast2Sample ) > LmaxRecent ) LmaxRecent = fabsf( LataLast2Sample );
		if (fabsf( LataLast1Sample ) > LmaxRecent ) LmaxRecent = fabsf( LataLast1Sample );
		if (fabsf( inputSampleL ) > LmaxRecent ) LmaxRecent = fabsf( inputSampleL );
		//this gives us something that won't cut out in zero crossings, to interpolate with
		
		RmaxRecent = fabsf( RataLast6Sample );
		if (fabsf( RataLast5Sample ) > RmaxRecent ) RmaxRecent = fabsf( RataLast5Sample );
		if (fabsf( RataLast4Sample ) > RmaxRecent ) RmaxRecent = fabsf( RataLast4Sample );
		if (fabsf( RataLast3Sample ) > RmaxRecent ) RmaxRecent = fabsf( RataLast3Sample );
		if (fabsf( RataLast2Sample ) > RmaxRecent ) RmaxRecent = fabsf( RataLast2Sample );
		if (fabsf( RataLast1Sample ) > RmaxRecent ) RmaxRecent = fabsf( RataLast1Sample );
		if (fabsf( inputSampleR ) > RmaxRecent ) RmaxRecent = fabsf( inputSampleR );
		//this gives us something that won't cut out in zero crossings, to interpolate with
		
		LmaxRecent *= 2.0f;
		RmaxRecent *= 2.0f;
		//by refclip this is 1.0 and fully into the antialiasing
		if (LmaxRecent > 1.0f) LmaxRecent = 1.0f;
		if (RmaxRecent > 1.0f) RmaxRecent = 1.0f;
		//and it tops out at 1. Higher means more antialiasing, lower blends into passThrough without antialiasing
		
		LataHalfwaySample -= Loverall;
		RataHalfwaySample -= Roverall;
		//subtract dist-cancel from input after getting raw input, before doing anything
		
		LdrySample = LataHalfwaySample;
		RdrySample = RataHalfwaySample;
		
		
		//begin L channel for the clipper
		if (LlastSample >= aw_f_refclip)
		{
			LlpDepth += 0.1f;
			if (LataHalfwaySample < aw_f_refclip)
			{
				LlastSample = ((aw_f_refclip*aw_f_hardness) + (LataHalfwaySample * aw_f_softness));
			}
			else LlastSample = aw_f_refclip;
		}
		
		if (LlastSample <= -aw_f_refclip)
		{
			LlpDepth += 0.1f;
			if (LataHalfwaySample > -aw_f_refclip)
			{
				LlastSample = ((-aw_f_refclip*aw_f_hardness) + (LataHalfwaySample * aw_f_softness));
			}
			else LlastSample = -aw_f_refclip;
		}
		
		if (LataHalfwaySample > aw_f_refclip)
		{
			LlpDepth += 0.1f;
			if (LlastSample < aw_f_refclip)
			{
				LataHalfwaySample = ((aw_f_refclip*aw_f_hardness) + (LlastSample * aw_f_softness));
			}
			else LataHalfwaySample = aw_f_refclip;
		}
		
		if (LataHalfwaySample < -aw_f_refclip)
		{
			LlpDepth += 0.1f;
			if (LlastSample > -aw_f_refclip)
			{
				LataHalfwaySample = ((-aw_f_refclip*aw_f_hardness) + (LlastSample * aw_f_softness));
			}
			else LataHalfwaySample = -aw_f_refclip;
		}
		///end L channel for the clipper
		
		//begin R channel for the clipper
		if (RlastSample >= aw_f_refclip)
		{
			RlpDepth += 0.1f;
			if (RataHalfwaySample < aw_f_refclip)
			{
				RlastSample = ((aw_f_refclip*aw_f_hardness) + (RataHalfwaySample * aw_f_softness));
			}
			else RlastSample = aw_f_refclip;
		}
		
		if (RlastSample <= -aw_f_refclip)
		{
			RlpDepth += 0.1f;
			if (RataHalfwaySample > -aw_f_refclip)
			{
				RlastSample = ((-aw_f_refclip*aw_f_hardness) + (RataHalfwaySample * aw_f_softness));
			}
			else RlastSample = -aw_f_refclip;
		}
		
		if (RataHalfwaySample > aw_f_refclip)
		{
			RlpDepth += 0.1f;
			if (RlastSample < aw_f_refclip)
			{
				RataHalfwaySample = ((aw_f_refclip*aw_f_hardness) + (RlastSample * aw_f_softness));
			}
			else RataHalfwaySample = aw_f_refclip;
		}
		
		if (RataHalfwaySample < -aw_f_refclip)
		{
			RlpDepth += 0.1f;
			if (RlastSample > -aw_f_refclip)
			{
				RataHalfwaySample = ((-aw_f_refclip*aw_f_hardness) + (RlastSample * aw_f_softness));
			}
			else RataHalfwaySample = -aw_f_refclip;
		}
		///end R channel for the clipper
		
        LoutputSample = LlastSample;
        RoutputSample = RlastSample;
		
		LlastSample = LataHalfwaySample;
		RlastSample = RataHalfwaySample;

		LataHalfwaySample = LoutputSample;
		RataHalfwaySample = RoutputSample;
		//swap around in a circle for one final ADClip,
		//this time not tracking overshoot anymore
		//end interpolated sample		
		//begin raw sample- inputSample and ataDrySample handled separately here
		
		inputSampleL -= Loverall;
		inputSampleR -= Roverall;
		//subtract dist-cancel from input after getting raw input, before doing anything
		
		LdrySample = inputSampleL;
		RdrySample = inputSampleR;
		
		//begin second L clip
		if (LlastSample >= aw_f_refclip)
		{
			LlpDepth += 0.1f;
			if (inputSampleL < aw_f_refclip)
			{
				LlastSample = ((aw_f_refclip*aw_f_hardness) + (inputSampleL * aw_f_softness));
			}
			else LlastSample = aw_f_refclip;
		}
		
		if (LlastSample <= -aw_f_refclip)
		{
			LlpDepth += 0.1f;
			if (inputSampleL > -aw_f_refclip)
			{
				LlastSample = ((-aw_f_refclip*aw_f_hardness) + (inputSampleL * aw_f_softness));
			}
			else LlastSample = -aw_f_refclip;
		}
		
		if (inputSampleL > aw_f_refclip)
		{
			LlpDepth += 0.1f;
			if (LlastSample < aw_f_refclip)
			{
				inputSampleL = ((aw_f_refclip*aw_f_hardness) + (LlastSample * aw_f_softness));
			}
			else inputSampleL = aw_f_refclip;
		}
		
		if (inputSampleL < -aw_f_refclip)
		{
			LlpDepth += 0.1f;
			if (LlastSample > -aw_f_refclip)
			{
				inputSampleL = ((-aw_f_refclip*aw_f_hardness) + (LlastSample * aw_f_softness));
			}
			else inputSampleL = -aw_f_refclip;
		}		
		//end second L clip
		
		//begin second R clip
		if (RlastSample >= aw_f_refclip)
		{
			RlpDepth += 0.1f;
			if (inputSampleR < aw_f_refclip)
			{
				RlastSample = ((aw_f_refclip*aw_f_hardness) + (inputSampleR * aw_f_softness));
			}
			else RlastSample = aw_f_refclip;
		}
		
		if (RlastSample <= -aw_f_refclip)
		{
			RlpDepth += 0.1f;
			if (inputSampleR > -aw_f_refclip)
			{
				RlastSample = ((-aw_f_refclip*aw_f_hardness) + (inputSampleR * aw_f_softness));
			}
			else RlastSample = -aw_f_refclip;
		}
		
		if (inputSampleR > aw_f_refclip)
		{
			RlpDepth += 0.1f;
			if (RlastSample < aw_f_refclip)
			{
				inputSampleR = ((aw_f_refclip*aw_f_hardness) + (RlastSample * aw_f_softness));
			}
			else inputSampleR = aw_f_refclip;
		}
		
		if (inputSampleR < -aw_f_refclip)
		{
			RlpDepth += 0.1f;
			if (RlastSample > -aw_f_refclip)
			{
				inputSampleR = ((-aw_f_refclip*aw_f_hardness) + (RlastSample * aw_f_softness));
			}
			else inputSampleR = -aw_f_refclip;
		}		
		//end second R clip
		
		LoutputSample = LlastSample;
		RoutputSample = RlastSample;
		LlastSample = inputSampleL;
		RlastSample = inputSampleR;
		inputSampleL = LoutputSample;
		inputSampleR = RoutputSample;
		
		LataHalfDrySample = (LataDrySample*ataK3)+(LataHalfDrySample*ataK4);
		LataHalfDiffSample = (LataHalfwaySample - LataHalfDrySample)* aw_inv0;
		LataLastDiffSample = LataDiffSample*ataK5;
		LataDiffSample = (inputSampleL - LataDrySample)* aw_inv0;
		LataDiffSample += LataHalfDiffSample;
		LataDiffSample -= LataLastDiffSample;
		inputSampleL = LataDrySample;
		inputSampleL += LataDiffSample;
		
		RataHalfDrySample = (RataDrySample*ataK3)+(RataHalfDrySample*ataK4);
		RataHalfDiffSample = (RataHalfwaySample - RataHalfDrySample)* aw_inv0;
		RataLastDiffSample = RataDiffSample*ataK5;
		RataDiffSample = (inputSampleR - RataDrySample)* aw_inv0;
		RataDiffSample += RataHalfDiffSample;
		RataDiffSample -= RataLastDiffSample;
		inputSampleR = RataDrySample;
		inputSampleR += RataDiffSample;
		
		Loverall = (Loverall * aw_f_cancelold) + (LataDiffSample * aw_f_cancelnew);
		Roverall = (Roverall * aw_f_cancelold) + (RataDiffSample * aw_f_cancelnew);
		//apply all the diffs to a lowpassed IIR

		
		if (flip)
		{
			LiirSampleA = (LiirSampleA * aw_f_altAmount) + (inputSampleL * aw_f_iirAmount);
			inputSampleL -= LiirSampleA;
			LiirSampleC = (LiirSampleC * aw_f_altAmount) + (LpassThrough * aw_f_iirAmount);
			LpassThrough -= LiirSampleC;
			
			RiirSampleA = (RiirSampleA * aw_f_altAmount) + (inputSampleR * aw_f_iirAmount);
			inputSampleR -= RiirSampleA;
			RiirSampleC = (RiirSampleC * aw_f_altAmount) + (RpassThrough * aw_f_iirAmount);
			RpassThrough -= RiirSampleC;
		}
		else
		{
			LiirSampleB = (LiirSampleB * aw_f_altAmount) + (inputSampleL * aw_f_iirAmount);
			inputSampleL -= LiirSampleB;
			LiirSampleD = (LiirSampleD * aw_f_altAmount) + (LpassThrough * aw_f_iirAmount);
			LpassThrough -= LiirSampleD;
			
			RiirSampleB = (RiirSampleB * aw_f_altAmount) + (inputSampleR * aw_f_iirAmount);
			inputSampleR -= RiirSampleB;
			RiirSampleD = (RiirSampleD * aw_f_altAmount) + (RpassThrough * aw_f_iirAmount);
			RpassThrough -= RiirSampleD;
		}
		flip = !flip;
		//highpass section 
		
		LlastOut3Sample = LlastOut2Sample;
		LlastOut2Sample = LlastOutSample;
		LlastOutSample = inputSampleL;
		
		RlastOut3Sample = RlastOut2Sample;
		RlastOut2Sample = RlastOutSample;
		RlastOutSample = inputSampleR;
		
		
		LlpDepth -= aw_f_lpSpeed;
		RlpDepth -= aw_f_lpSpeed;

		if (LlpDepth > 0.0f)
		{
			if (LlpDepth > 1.0f) LlpDepth = 1.0f;
			inputSampleL *= (1.0f-LlpDepth);
			inputSampleL += (((LlastOutSample + LlastOut2Sample + LlastOut3Sample) * aw_inv1)*LlpDepth);
		}
		
		if (RlpDepth > 0.0f)
		{
			if (RlpDepth > 1.0f) RlpDepth = 1.0f;
			inputSampleR *= (1.0f-RlpDepth);
			inputSampleR += (((RlastOutSample + RlastOut2Sample + RlastOut3Sample) * aw_inv1)*RlpDepth);
		}
		
		if (LlpDepth < 0.0f) LlpDepth = 0.0f;
		if (RlpDepth < 0.0f) RlpDepth = 0.0f;
		fpdL ^= fpdL << 13; fpdL ^= fpdL >> 17; fpdL ^= fpdL << 5;
		fpdR ^= fpdR << 13; fpdR ^= fpdR >> 17; fpdR ^= fpdR << 5;
		//end 32 bit stereo floating point dither
		
		inputSampleL *= (1.0f-LmaxRecent);
		inputSampleR *= (1.0f-RmaxRecent);
		inputSampleL += (LpassThrough * LmaxRecent);
		inputSampleR += (RpassThrough * RmaxRecent);
		//there's our raw signal, without antialiasing. Brings up low level stuff and softens more when hot
		
		if (inputSampleL > aw_f_cliplevel) inputSampleL = aw_f_cliplevel;
		if (inputSampleL < -aw_f_cliplevel) inputSampleL = -aw_f_cliplevel;
		if (inputSampleR > aw_f_cliplevel) inputSampleR = aw_f_cliplevel;
		if (inputSampleR < -aw_f_cliplevel) inputSampleR = -aw_f_cliplevel;
		//final iron bar
		

		aw_outL = inputSampleL;
		aw_outR = inputSampleR;
    /* aw:end */		AW_OUT_FAST(aw_out, aw_channels, aw_outL, aw_outR);
		aw_in += aw_channels;
		aw_out += aw_channels;
	}
}
    aw_s->LataLast6Sample = LataLast6Sample;
    aw_s->LataLast5Sample = LataLast5Sample;
    aw_s->LataLast4Sample = LataLast4Sample;
    aw_s->LataLast3Sample = LataLast3Sample;
    aw_s->LataLast2Sample = LataLast2Sample;
    aw_s->LataLast1Sample = LataLast1Sample;
    aw_s->LataHalfwaySample = LataHalfwaySample;
    aw_s->LataHalfDrySample = LataHalfDrySample;
    aw_s->LataHalfDiffSample = LataHalfDiffSample;
    aw_s->LataLastDiffSample = LataLastDiffSample;
    aw_s->LataDrySample = LataDrySample;
    aw_s->LataDiffSample = LataDiffSample;
    aw_s->RataLast6Sample = RataLast6Sample;
    aw_s->RataLast5Sample = RataLast5Sample;
    aw_s->RataLast4Sample = RataLast4Sample;
    aw_s->RataLast3Sample = RataLast3Sample;
    aw_s->RataLast2Sample = RataLast2Sample;
    aw_s->RataLast1Sample = RataLast1Sample;
    aw_s->RataHalfwaySample = RataHalfwaySample;
    aw_s->RataHalfDrySample = RataHalfDrySample;
    aw_s->RataHalfDiffSample = RataHalfDiffSample;
    aw_s->RataLastDiffSample = RataLastDiffSample;
    aw_s->RataDrySample = RataDrySample;
    aw_s->RataDiffSample = RataDiffSample;
    aw_s->LlastSample = LlastSample;
    aw_s->LlastOutSample = LlastOutSample;
    aw_s->LlastOut2Sample = LlastOut2Sample;
    aw_s->LlastOut3Sample = LlastOut3Sample;
    aw_s->LlpDepth = LlpDepth;
    aw_s->Loverall = Loverall;
    aw_s->LiirSampleA = LiirSampleA;
    aw_s->LiirSampleB = LiirSampleB;
    aw_s->LiirSampleC = LiirSampleC;
    aw_s->LiirSampleD = LiirSampleD;
    aw_s->RlastSample = RlastSample;
    aw_s->RlastOutSample = RlastOutSample;
    aw_s->RlastOut2Sample = RlastOut2Sample;
    aw_s->RlastOut3Sample = RlastOut3Sample;
    aw_s->RlpDepth = RlpDepth;
    aw_s->Roverall = Roverall;
    aw_s->RiirSampleA = RiirSampleA;
    aw_s->RiirSampleB = RiirSampleB;
    aw_s->RiirSampleC = RiirSampleC;
    aw_s->RiirSampleD = RiirSampleD;
    aw_s->flip = flip;
    aw_s->fpdL = fpdL;
    aw_s->fpdR = fpdR;
}

